use std::fs
use std::collections::HashMap

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut acc: HashMap<string, int> = HashMap::new()
    for line in text.lines() {
        let p: Vec<string> = line.split_whitespace().map(|s| s.to_string()).collect()
        if p.len() == 0 {
            continue
        }
        let cmd = p[0].clone()
        if cmd == "balance" {
            let name = p[1].clone()
            if acc.contains_key(name.as_str()) {
                println("${acc[name.as_str()]}")
            } else {
                println("error: unknown account ${name}")
            }
        } else if cmd == "open" {
            let name = p[1].clone()
            let amt: int = p[2].parse().unwrap_or(0)
            if amt < 0 {
                println("error: invalid amount")
            } else if acc.contains_key(name.as_str()) {
                println("error: duplicate account")
            } else {
                acc.insert(name, amt)
                println("ok")
            }
        } else if cmd == "deposit" || cmd == "withdraw" {
            let name = p[1].clone()
            let amt: int = p[2].parse().unwrap_or(0)
            if amt <= 0 {
                println("error: invalid amount")
            } else if !acc.contains_key(name.as_str()) {
                println("error: unknown account ${name}")
            } else {
                let bal: int = acc[name.as_str()]
                if cmd == "deposit" {
                    acc.insert(name, bal + amt)
                    println("ok")
                } else if bal < amt {
                    println("error: insufficient funds")
                } else {
                    acc.insert(name, bal - amt)
                    println("ok")
                }
            }
        } else if cmd == "transfer" {
            let from = p[1].clone()
            let to = p[2].clone()
            let amt: int = p[3].parse().unwrap_or(0)
            if amt <= 0 {
                println("error: invalid amount")
            } else if !acc.contains_key(from.as_str()) {
                println("error: unknown account ${from}")
            } else if !acc.contains_key(to.as_str()) {
                println("error: unknown account ${to}")
            } else if from == to {
                println("error: same account")
            } else {
                let fb: int = acc[from.as_str()]
                let tb: int = acc[to.as_str()]
                if fb < amt {
                    println("error: insufficient funds")
                } else {
                    acc.insert(from, fb - amt)
                    acc.insert(to, tb + amt)
                    println("ok")
                }
            }
        }
    }
    let mut keys: Vec<string> = []
    for k in acc.keys() {
        keys.push(k.clone())
    }
    keys.sort()
    for k in keys {
        println("${k} ${acc[k.as_str()]}")
    }
}

